    frompat = alloc(repl_from_len + 7);
    if (frompat == NULL)
	return;
    frompatlen = vim_snprintf((char *)frompat, repl_from_len + 7, "\\V\\<%s\\>", repl_from);
    curwin->w_cursor.lnum = 0;
