	    {
		++sub_nlines;
		prev_lnum = curwin->w_cursor.lnum;
	    }
	    ++sub_nsubs;
	}
	curwin->w_cursor.col += (colnr_T)repl_to_len;
    }
    curwin->w_cursor = pos;
    vim_free(frompat);
    if (sub_nsubs == 0)
	semsg(_(e_not_found_str), repl_from);
