		if (spats[0].off.end)
		    off_buf[off_len++] = 'e';
		else if (!spats[0].off.line)
		    off_buf[off_len++] = 's';
		if (spats[0].off.off > 0 || spats[0].off.line)
		    off_buf[off_len++] = '+';
		off_buf[off_len] = NUL;
		if (spats[0].off.off != 0 || spats[0].off.line)
