    int
ExpandBufnames(
    char_u	*pat,
    int		*num_file,
    char_u	***file,
    int		options)
{
    *file = NULL;
    fuzzy = cmdline_fuzzy_complete(pat);
    if (!fuzzy)
    {
	if (*pat == '^' && pat[1] != NUL)
	{
	    int  len = (int)STRLEN(pat);
	    patc = alloc(len);
	    if (patc == NULL)
		return FAIL;
	    STRNCPY(patc, pat + 1, len - 1);
	    patc[len - 1] = NUL;
	}
	else if (*pat == '^')
	    patc = (char_u *)"";
	    patc = pat;
	regmatch.regprog = vim_regcomp(patc, RE_MAGIC);
    }
    for (round = 1; round <= 2; ++round)
    {
	count = 0;
	FOR_ALL_BUFFERS(buf)
	    if (!fuzzy)
		if (regmatch.regprog == NULL)
		    if (to_free)
			vim_free(patc);
		    return FAIL;
		p = buflist_match(&regmatch, buf, p_wic);
		p = NULL;
		if ((score = fuzzy_match_str(buf->b_sfname, pat)) != 0)
		    p = buf->b_sfname;
		if (p == NULL)
		    if ((score = fuzzy_match_str(buf->b_ffname, pat)) != 0)
			p = buf->b_ffname;
	    if (round == 1)
		++count;
	    if (options & WILD_HOME_REPLACE)
		p = home_replace_save(buf, p);
		p = vim_strsave(p);
	    if (!fuzzy)
	    {
#ifdef FEAT_VIMINFO
		if (matches != NULL)
		{
		    matches[count].buf = buf;
		    matches[count].match = p;
		    count++;
		}
		else
#endif
		    (*file)[count++] = p;  // The line where the warning is located
	    }
	    else
	    {
		fuzmatch[count].idx = count;
		fuzmatch[count].str = p;
		fuzmatch[count].score = score;
		count++;
	    }
	if (count == 0)	// no match found, break here
	    break;
	if (round == 1)
	{
	    if (!fuzzy)
	    {
		if (*file == NULL)
		{
		    vim_regfree(regmatch.regprog);
		    if (to_free)
			vim_free(patc);
		    return FAIL;
		}
	    }
	    else
	    {
		fuzmatch = ALLOC_MULT(fuzmatch_str_T, count);
		if (fuzmatch == NULL)
		{
		    *num_file = 0;
		    *file = NULL;
		    return FAIL;
		}
	    }
	}
    }
    if (!fuzzy)
    {
	vim_regfree(regmatch.regprog);
	if (to_free)
	    vim_free(patc);
    }
    *num_file = count;
    return (count == 0 ? FAIL : OK);
}


