    {
	if (*s == NUL)
	{
	    if (did_curdir)
		break;
	    flags |= EW_DIR;
	    e = s;
	    pathlen = 0;
	    seplen = 0;
	}
	else
	{
#if defined(MSWIN)
	    e = vim_strchr(s, ':');
#endif
	    if (e == NULL)
		e = s + STRLEN(s);
	    pathlen = (size_t)(e - s);
	    if (STRNCMP(s, ".", pathlen) == 0)
	    {
		flags |= EW_DIR;
	    }
	    else
		flags &= ~EW_DIR;
	    seplen = !after_pathsep(s, e) ? STRLEN_LITERAL(PATHSEPSTR) : 0;
	}
