                i += 2;
        }
        o = lookupKeyWrite(c->db,c->argv[2]);
        if (o) {
            if (checkType(c,o,OBJ_STREAM)) return;
            s = o->ptr;
        }
        grpname = c->argv[3]->ptr;
    }
    if (c->argc >= 4 && !mkstream) {
    }
        streamID id;
        if (!strcmp(c->argv[4]->ptr,"$")) {
            if (s) {
