                if (submix_layout->layout_type == 2) {
                    ret = av_channel_layout_describe(&submix_layout->sound_system, buf, sizeof(buf));
                    if (ret >= 0)
                        av_log(NULL, AV_LOG_INFO, " %s", buf);
