    if (ret < 0) {
        av_frame_free(&out);
        return ret;
    }
    ret = av_frame_copy(out, frame);
    if (ret < 0) {
        av_frame_free(&out);
        return ret;
    }
    av_frame_free(&frame);
    *rframe = out;
    return 0;
}


