                    stat[i] += FFABS(bg + ((br*rct_y_coeff[i][0] + bb*rct_y_coeff[i][1])>>2));
                }
            }
            sample[0][x] = ag;
            sample[1][x] = ab;
            sample[2][x] = ar;
            lastr = r;
            lastg = g;
            lastb = b;
