       || (h->last_pocs[H264_MAX_DPB_FRAMES-2] > INT_MIN && h->last_pocs[H264_MAX_DPB_FRAMES-1] - (int64_t)h->last_pocs[H264_MAX_DPB_FRAMES-2] > 2))
        out_of_order = FFMAX(out_of_order, 1);
    if (out_of_order == H264_MAX_DPB_FRAMES) {
