  next_c_start = next_c;
  str_byte_start = str_byte;
  next_tags = NULL;
  for (trans_i = tnfa->initial; trans_i->state; trans_i++)
    {
      if (state == NULL)
	{
	  state = trans_i->state;
	  next_tags = trans_i->tags;
	}
      else
	{
	  BT_STACK_PUSH(pos, str_byte, 0, trans_i->state,
	  {
	    int *tmp = trans_i->tags;
	    if (tmp)
	      while (*tmp >= 0)
		stack->item.tags[*tmp++] = pos;
