		default_window_size(sc->tc, s, NULL, &sx, &sy, &xpixel, &ypixel,
		    -1);
		if (s->curw == NULL)
			s->curw = sc->wl;
		sc->wl->session = s;
		w->latest = sc->tc;
		winlink_set_window(sc->wl, w);
	sc->flags |= SPAWN_NONOTIFY;
	wp = spawn_pane(sc, cause);
	if (~sc->flags & SPAWN_RESPAWN) {
		if (sc->name != NULL) {
