  int i;

  for(i = 0, cur = crt; cur; ++i, cur = cur->next);
  result = Curl_ssl_init_certinfo(data, i);

  for(i = 0, cur = crt; result == CURLE_OK && cur; ++i, cur = cur->next) {
    const char *beg = (const char *) cur->raw.p;
