// Function: do_file_type from current file (lines 202-211)
static int do_file_type(const char *type)
{
  if(!type || !type[0])
    return SSL_FILETYPE_PEM;
  if(strcasecompare(type, "PEM"))
    return SSL_FILETYPE_PEM;
  if(strcasecompare(type, "DER"))
    return SSL_FILETYPE_ASN1;
  return -1;
}

// Macro: use_sni from current file (line 377)
#define use_sni(x)  sni = (x)

// Function: wolfSSL_KeepArrays from current file (lines 150-151)
    /* Should never happen as wolfSSL_KeepArrays() was called before. */
    return 0;

