static char *handle_path_level_conflicts(struct merge_options *opt,
					 const char *path,
					 struct dir_rename_entry *entry,
					 struct hashmap *collisions,
	new_path = apply_dir_rename(entry, path);
	if (!new_path) {
	collision_ent = collision_find_entry(collisions, new_path);
	if (!collision_ent)
	if (collision_ent->reported_already) {  // The line where the warning is located
		clean = 0;
	} else if (tree_has_path(opt->repo, tree, new_path)) {
		collision_ent->reported_already = 1;
		strbuf_add_separated_string_list(&collision_paths, ", ",
						 &collision_ent->source_files);
		output(opt, 1, _("CONFLICT (implicit dir rename): Existing "
		       new_path, collision_paths.buf);
		clean = 0;
	} else if (collision_ent->source_files.nr > 1) {
		collision_ent->reported_already = 1;
		strbuf_add_separated_string_list(&collision_paths, ", ",
						 &collision_ent->source_files);
		output(opt, 1, _("CONFLICT (implicit dir rename): Cannot map "
		       new_path, collision_paths.buf);
		clean = 0;
	if (!clean && new_path) {
		free(new_path);
		return NULL;
	return new_path;
	}
